import{_ as e,r as o,o as c,c as i,e as l,a as s,b as a,d as p}from"./app-6c9584fa.js";const u={},r={href:"https://git-scm.com/docs/git-worktree",target:"_blank",rel:"noopener noreferrer"},k={href:"https://docs.anthropic.com/en/docs/managing-context-windows",target:"_blank",rel:"noopener noreferrer"};function d(m,n){const t=o("ExternalLinkIcon");return c(),i("div",null,[n[4]||(n[4]=l(`<h1 id="第四章-我是如何扒开-claude-code-记忆与上下文压缩机制的" tabindex="-1"><a class="header-anchor" href="#第四章-我是如何扒开-claude-code-记忆与上下文压缩机制的" aria-hidden="true">#</a> 第四章：我是如何扒开 Claude Code 记忆与上下文压缩机制的</h1><p>大家好。今天，我们将来到 Claude Code 源码剖析之旅的最后一站。</p><p>在前面三章，我们了解了系统的架构、看懂了查询循环，也知道它是怎么挥动“工具”这把利剑的。但如果没有“记忆”，再强大的大脑也只是一条七秒记忆的金鱼。</p><p>你一定遇到过这种绝望的时刻：</p><ul><li>排查一个 Bug 聊了半个小时，大模型突然开始“失忆”，连刚才改过什么文件都忘了；</li><li>或者你一次性塞给它整个项目的日志，结果直接报 <code>400 Token Limit Exceeded</code>，连话都不让说了。</li></ul><p>面对动辄几万行的代码库和漫长的排查过程，Claude Code 是如何做到“不遗忘关键信息”同时又“不撑爆 Token 预算”的？遇到需要独立试错的子任务，它又是如何做到分身乏术的？</p><p>今天，我们就深入 <code>src/services/compact/</code>、<code>src/memdir/</code> 和 <code>src/tools/AgentTool/</code> 的源码，一探究竟。</p><p>学习完这章后，你会对以下内容有清晰的认识：</p><ol><li><strong>断臂求生：</strong> 连压缩请求本身都超载了，系统该怎么自救？</li><li><strong>反共识的记忆：</strong> 没有向量数据库，它是怎么管理全局记忆的？</li><li><strong>Agent 分身术：</strong> 它是如何开小号、在沙箱里安全试错的？</li><li><strong>动手实践：</strong> 像官方一样，用几十行代码写一个自己的记忆管理器。</li></ol><hr><h2 id="一、断臂求生-上下文压缩机制-context-compression" tabindex="-1"><a class="header-anchor" href="#一、断臂求生-上下文压缩机制-context-compression" aria-hidden="true">#</a> 一、断臂求生：上下文压缩机制（Context Compression）</h2><p>在大模型 API 中，上下文窗口不仅是有限的，而且越长越贵。当对话历史越来越长，Claude Code 会主动触发压缩机制（Compact），把历史记录精简。</p><p>我们来看看 <code>src/services/compact/compact.ts</code> 里的魔鬼细节。</p><h3 id="_1-极致的-token-抠门-剥离图片与冗余件" tabindex="-1"><a class="header-anchor" href="#_1-极致的-token-抠门-剥离图片与冗余件" aria-hidden="true">#</a> 1. 极致的 Token 抠门：剥离图片与冗余件</h3><p>在请求大模型做对话总结之前，系统会做一次“大瘦身”。因为把几兆的截图重新发给模型，仅仅为了让它生成一句“刚才用户发了一张报错截图”，是极度浪费钱的。</p><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token comment">// 摘自 src/services/compact/compact.ts</span>
<span class="token keyword">export</span> <span class="token keyword">function</span> <span class="token function">stripImagesFromMessages</span><span class="token punctuation">(</span>messages<span class="token operator">:</span> Message<span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token operator">:</span> Message<span class="token punctuation">[</span><span class="token punctuation">]</span> <span class="token punctuation">{</span>
  <span class="token keyword">return</span> messages<span class="token punctuation">.</span><span class="token function">map</span><span class="token punctuation">(</span>message <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>message<span class="token punctuation">.</span>type <span class="token operator">!==</span> <span class="token string">&#39;user&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
      <span class="token keyword">return</span> message
    <span class="token punctuation">}</span>

    <span class="token keyword">const</span> content <span class="token operator">=</span> message<span class="token punctuation">.</span>message<span class="token punctuation">.</span>content
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token builtin">Array</span><span class="token punctuation">.</span><span class="token function">isArray</span><span class="token punctuation">(</span>content<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
      <span class="token keyword">return</span> message
    <span class="token punctuation">}</span>

    <span class="token comment">// 扫描内容，将真实的图片和文档数据替换为纯文本占位符</span>
    <span class="token keyword">let</span> hasMediaBlock <span class="token operator">=</span> <span class="token boolean">false</span>
    <span class="token keyword">const</span> newContent <span class="token operator">=</span> content<span class="token punctuation">.</span><span class="token function">flatMap</span><span class="token punctuation">(</span>block <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
      <span class="token keyword">if</span> <span class="token punctuation">(</span>block<span class="token punctuation">.</span>type <span class="token operator">===</span> <span class="token string">&#39;image&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        hasMediaBlock <span class="token operator">=</span> <span class="token boolean">true</span>
        <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token punctuation">{</span> type<span class="token operator">:</span> <span class="token string">&#39;text&#39;</span> <span class="token keyword">as</span> <span class="token keyword">const</span><span class="token punctuation">,</span> text<span class="token operator">:</span> <span class="token string">&#39;[image]&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">]</span>
      <span class="token punctuation">}</span>
      <span class="token keyword">if</span> <span class="token punctuation">(</span>block<span class="token punctuation">.</span>type <span class="token operator">===</span> <span class="token string">&#39;document&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        hasMediaBlock <span class="token operator">=</span> <span class="token boolean">true</span>
        <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token punctuation">{</span> type<span class="token operator">:</span> <span class="token string">&#39;text&#39;</span> <span class="token keyword">as</span> <span class="token keyword">const</span><span class="token punctuation">,</span> text<span class="token operator">:</span> <span class="token string">&#39;[document]&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">]</span>
      <span class="token punctuation">}</span>
      <span class="token keyword">return</span> <span class="token punctuation">[</span>block<span class="token punctuation">]</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span>
    <span class="token comment">// ...</span>
  <span class="token punctuation">}</span><span class="token punctuation">)</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>把图片和长文档直接替换成 <code>[image]</code> 占位符，不仅节省了巨大的开销，还保证了逻辑的连贯性。</p><h3 id="_2-绝境逃生舱-ptl-prompt-too-long-重试" tabindex="-1"><a class="header-anchor" href="#_2-绝境逃生舱-ptl-prompt-too-long-重试" aria-hidden="true">#</a> 2. 绝境逃生舱：PTL (Prompt Too Long) 重试</h3><p>这个是我在源码里看到的最硬核的设计之一。</p><p>你想想，如果用户一次性塞入了太多巨大的文件，导致<strong>连“发起压缩总结”这个请求本身，都超过了 API 的最大 Token 限制</strong>怎么办？按照普通逻辑，系统直接就死锁崩溃了。</p><p>源码里专门写了一个 <code>truncateHeadForPTLRetry</code> 逃生舱函数：</p><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token comment">// 摘自 src/services/compact/compact.ts</span>
<span class="token keyword">export</span> <span class="token keyword">function</span> <span class="token function">truncateHeadForPTLRetry</span><span class="token punctuation">(</span>
  messages<span class="token operator">:</span> Message<span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
  ptlResponse<span class="token operator">:</span> AssistantMessage<span class="token punctuation">,</span>
<span class="token punctuation">)</span><span class="token operator">:</span> Message<span class="token punctuation">[</span><span class="token punctuation">]</span> <span class="token operator">|</span> <span class="token keyword">null</span> <span class="token punctuation">{</span>
  <span class="token comment">// ... (省略部分重试标记剥离逻辑)</span>
  <span class="token keyword">const</span> groups <span class="token operator">=</span> <span class="token function">groupMessagesByApiRound</span><span class="token punctuation">(</span>input<span class="token punctuation">)</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span>groups<span class="token punctuation">.</span>length <span class="token operator">&lt;</span> <span class="token number">2</span><span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token keyword">null</span>

  <span class="token keyword">const</span> tokenGap <span class="token operator">=</span> <span class="token function">getPromptTooLongTokenGap</span><span class="token punctuation">(</span>ptlResponse<span class="token punctuation">)</span>
  <span class="token keyword">let</span> dropCount<span class="token operator">:</span> <span class="token builtin">number</span>
  
  <span class="token keyword">if</span> <span class="token punctuation">(</span>tokenGap <span class="token operator">!==</span> <span class="token keyword">undefined</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// 如果 API 明确告诉了超出的 Token 数量，精准计算要丢弃几轮</span>
    <span class="token keyword">let</span> acc <span class="token operator">=</span> <span class="token number">0</span>
    dropCount <span class="token operator">=</span> <span class="token number">0</span>
    <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">const</span> g <span class="token keyword">of</span> groups<span class="token punctuation">)</span> <span class="token punctuation">{</span>
      acc <span class="token operator">+=</span> <span class="token function">roughTokenCountEstimationForMessages</span><span class="token punctuation">(</span>g<span class="token punctuation">)</span>
      dropCount<span class="token operator">++</span>
      <span class="token keyword">if</span> <span class="token punctuation">(</span>acc <span class="token operator">&gt;=</span> tokenGap<span class="token punctuation">)</span> <span class="token keyword">break</span>
    <span class="token punctuation">}</span>
  <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token punctuation">{</span>
    <span class="token comment">// 当连压缩请求都超载，且不知道超出多少时，默认抛弃最老的 20% 历史记录</span>
    dropCount <span class="token operator">=</span> Math<span class="token punctuation">.</span><span class="token function">max</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">,</span> Math<span class="token punctuation">.</span><span class="token function">floor</span><span class="token punctuation">(</span>groups<span class="token punctuation">.</span>length <span class="token operator">*</span> <span class="token number">0.2</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
  <span class="token punctuation">}</span>

  <span class="token comment">// 直接丢弃头部消息，保留最新内容</span>
  <span class="token keyword">const</span> sliced <span class="token operator">=</span> groups<span class="token punctuation">.</span><span class="token function">slice</span><span class="token punctuation">(</span>dropCount<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">flat</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
  <span class="token keyword">return</span> sliced
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>官方注释里写得很明白：“This is the last-resort escape hatch... Dropping the oldest context is lossy but unblocks them.”（这是最后的逃生舱，丢弃最老的上下文虽然有损，但能防止对话彻底卡死）。真金白银买来的经验！</p><hr><h2 id="二、大道至简-基于文件系统的记忆机制" tabindex="-1"><a class="header-anchor" href="#二、大道至简-基于文件系统的记忆机制" aria-hidden="true">#</a> 二、大道至简：基于文件系统的记忆机制</h2><p>外界一直有很多猜测，觉得 Claude Code 这么聪明，肯定是偷偷连了一个强大的向量数据库（Vector DB）来管理长期记忆。</p><p><strong>但当我翻开 <code>src/memdir/memdir.ts</code> 的源码时，大跌眼镜。</strong></p><p>它根本没有什么高深莫测的数据库组件，而是极其务实地利用了<strong>本地文件系统</strong>，外加一段堪称教科书级别的 <code>System Prompt</code>。</p><h3 id="_1-教模型做笔记-两步走法则" tabindex="-1"><a class="header-anchor" href="#_1-教模型做笔记-两步走法则" aria-hidden="true">#</a> 1. 教模型做笔记：两步走法则</h3><p>在系统启动时，框架会给大模型注入这样一段 Prompt，手把手教它怎么存记忆：</p><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token comment">// 摘自 src/memdir/memdir.ts 中的 buildMemoryLines 函数</span>
<span class="token keyword">const</span> howToSave <span class="token operator">=</span> <span class="token punctuation">[</span>
  <span class="token string">&#39;## How to save memories&#39;</span><span class="token punctuation">,</span>
  <span class="token string">&#39;&#39;</span><span class="token punctuation">,</span>
  <span class="token string">&#39;Saving a memory is a two-step process:&#39;</span><span class="token punctuation">,</span>
  <span class="token string">&#39;&#39;</span><span class="token punctuation">,</span>
  <span class="token string">&#39;**Step 1** — write the memory to its own file (e.g., \`user_role.md\`, \`feedback_testing.md\`) using this frontmatter format:&#39;</span><span class="token punctuation">,</span>
  <span class="token comment">// ... 写入带有 name, description, type 的 Markdown Frontmatter</span>
  <span class="token string">&#39;&#39;</span><span class="token punctuation">,</span>
  <span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">**Step 2** — add a pointer to that file in \\\`</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span><span class="token constant">ENTRYPOINT_NAME</span><span class="token interpolation-punctuation punctuation">}</span></span><span class="token string">\\\`. \\\`</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span><span class="token constant">ENTRYPOINT_NAME</span><span class="token interpolation-punctuation punctuation">}</span></span><span class="token string">\\\` is an index, not a memory — each entry should be one line, under ~150 characters...</span><span class="token template-punctuation string">\`</span></span>
<span class="token punctuation">]</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>原来，大模型是被这套规则“规训”出来的：</p><ol><li>先用常规的文件写入工具把详细记忆（比如代码规范、某个 Bug 的前因后果）写进具体的 <code>.md</code> 文件。</li><li>然后再去修改 <code>MEMORY.md</code>（记忆的目录索引），在里面加一行带链接的超短描述。</li></ol><h3 id="_2-严防死守的防爆机制" tabindex="-1"><a class="header-anchor" href="#_2-严防死守的防爆机制" aria-hidden="true">#</a> 2. 严防死守的防爆机制</h3><p>因为 <code>MEMORY.md</code> 就像一本书的目录，它会被无条件塞入你的每一次对话上下文。如果模型把目录写成了流水账，Token 早就爆了。</p><p>于是源码里做了一件非常暴力的事——<strong>强制截断加警告</strong>：</p><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token comment">// 摘自 src/memdir/memdir.ts</span>
<span class="token keyword">export</span> <span class="token keyword">const</span> <span class="token constant">ENTRYPOINT_NAME</span> <span class="token operator">=</span> <span class="token string">&#39;MEMORY.md&#39;</span>
<span class="token keyword">export</span> <span class="token keyword">const</span> <span class="token constant">MAX_ENTRYPOINT_LINES</span> <span class="token operator">=</span> <span class="token number">200</span>  <span class="token comment">// 强制死命令：最多 200 行</span>
<span class="token keyword">export</span> <span class="token keyword">const</span> <span class="token constant">MAX_ENTRYPOINT_BYTES</span> <span class="token operator">=</span> <span class="token number">25_000</span> <span class="token comment">// 强制死命令：最多约 25KB</span>

<span class="token keyword">export</span> <span class="token keyword">function</span> <span class="token function">truncateEntrypointContent</span><span class="token punctuation">(</span>raw<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">)</span><span class="token operator">:</span> EntrypointTruncation <span class="token punctuation">{</span>
  <span class="token comment">// ...</span>
  <span class="token keyword">const</span> reason <span class="token operator">=</span> wasByteTruncated <span class="token operator">&amp;&amp;</span> <span class="token operator">!</span>wasLineTruncated
    <span class="token operator">?</span> <span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span><span class="token function">formatFileSize</span><span class="token punctuation">(</span>byteCount<span class="token punctuation">)</span><span class="token interpolation-punctuation punctuation">}</span></span><span class="token string"> (limit: </span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span><span class="token function">formatFileSize</span><span class="token punctuation">(</span><span class="token constant">MAX_ENTRYPOINT_BYTES</span><span class="token punctuation">)</span><span class="token interpolation-punctuation punctuation">}</span></span><span class="token string">) — index entries are too long</span><span class="token template-punctuation string">\`</span></span>
    <span class="token operator">:</span> wasLineTruncated <span class="token operator">&amp;&amp;</span> <span class="token operator">!</span>wasByteTruncated
      <span class="token operator">?</span> <span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>lineCount<span class="token interpolation-punctuation punctuation">}</span></span><span class="token string"> lines (limit: </span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span><span class="token constant">MAX_ENTRYPOINT_LINES</span><span class="token interpolation-punctuation punctuation">}</span></span><span class="token string">)</span><span class="token template-punctuation string">\`</span></span>
      <span class="token operator">:</span> <span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>lineCount<span class="token interpolation-punctuation punctuation">}</span></span><span class="token string"> lines and </span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span><span class="token function">formatFileSize</span><span class="token punctuation">(</span>byteCount<span class="token punctuation">)</span><span class="token interpolation-punctuation punctuation">}</span></span><span class="token template-punctuation string">\`</span></span>

  <span class="token keyword">return</span> <span class="token punctuation">{</span>
    <span class="token comment">// 暴力截断，并在末尾贴上大字报警告！</span>
    content<span class="token operator">:</span> truncated <span class="token operator">+</span> <span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">\\n\\n&gt; WARNING: </span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span><span class="token constant">ENTRYPOINT_NAME</span><span class="token interpolation-punctuation punctuation">}</span></span><span class="token string"> is </span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>reason<span class="token interpolation-punctuation punctuation">}</span></span><span class="token string">. Only part of it was loaded. Keep index entries to one line under ~200 chars...</span><span class="token template-punctuation string">\`</span></span><span class="token punctuation">,</span>
    <span class="token comment">// ...</span>
  <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>一旦超标，系统直接从末尾一刀切，并附上大写加粗的 <code>&gt; WARNING:</code>。大模型下次读到这句警告，自己就会吓得去精简索引文件了。这种用 Prompt 反向控制 AI 行为的设计，非常精妙。</p><hr><h2 id="三、分身术-agenttool-与子代理机制" tabindex="-1"><a class="header-anchor" href="#三、分身术-agenttool-与子代理机制" aria-hidden="true">#</a> 三、分身术：AgentTool 与子代理机制</h2><p>不知道你有没有想过，大模型在帮我重构某个核心模块时，万一把代码全改炸了怎么办？或者我想让它一边跑几十个单元测试，一边跟我讨论需求，它能做到吗？</p><p>答案在 <code>src/tools/AgentTool/AgentTool.tsx</code> 里。它可以派生子代理。</p><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token comment">// 摘自 src/tools/AgentTool/AgentTool.tsx</span>
<span class="token keyword">const</span> fullInputSchema <span class="token operator">=</span> <span class="token function">lazySchema</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
  <span class="token keyword">const</span> multiAgentInputSchema <span class="token operator">=</span> z<span class="token punctuation">.</span><span class="token function">object</span><span class="token punctuation">(</span><span class="token punctuation">{</span>
    name<span class="token operator">:</span> z<span class="token punctuation">.</span><span class="token function">string</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">optional</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">describe</span><span class="token punctuation">(</span><span class="token string">&#39;Name for the spawned agent...&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
    team_name<span class="token operator">:</span> z<span class="token punctuation">.</span><span class="token function">string</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">optional</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">describe</span><span class="token punctuation">(</span><span class="token string">&#39;Team name for spawning...&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
    <span class="token comment">// ...</span>
  <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">return</span> <span class="token function">baseInputSchema</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">merge</span><span class="token punctuation">(</span>multiAgentInputSchema<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token punctuation">{</span>
    isolation<span class="token operator">:</span> z<span class="token punctuation">.</span><span class="token function">enum</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string">&#39;worktree&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;remote&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">optional</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
      <span class="token punctuation">.</span><span class="token function">describe</span><span class="token punctuation">(</span><span class="token string">&#39;Isolation mode. &quot;worktree&quot; creates a temporary git worktree so the agent works on an isolated copy of the repo.&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
    cwd<span class="token operator">:</span> z<span class="token punctuation">.</span><span class="token function">string</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">optional</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
    run_in_background<span class="token operator">:</span> z<span class="token punctuation">.</span><span class="token function">boolean</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">optional</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
  <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>仔细看里面的三个核心字段，这绝对是高级程序员才能想出来的骚操作：</p><ol><li><strong>后台运行 (<code>run_in_background</code>)</strong>：当设为 <code>true</code> 时，大模型派生出小弟后，主进程不会傻等。系统返回一个 <code>async_launched</code> 状态，大模型可以接着跟你聊天，过一会儿再去读取小弟的输出日志。</li><li><strong>绝对隔离 (<code>isolation: &#39;worktree&#39;</code>)</strong>：这是最让我惊艳的设计！当大模型需要做破坏性实验时，底层会自动调用 <code>git worktree add</code> 创建一个平行的物理克隆目录。子代理在这个沙箱里随便造，完全不会弄脏你当前的开发分支！</li><li><strong>团队协作 (<code>team_name</code> &amp; <code>name</code>)</strong>：主代理不仅能创建助手，还能给它起名字。在实验特性下，甚至能通过 tmux 劈开一个新面板，让两个 AI 在你面前结对编程。</li></ol><hr><h2 id="四、动手实践-写一个极简的记忆管理器" tabindex="-1"><a class="header-anchor" href="#四、动手实践-写一个极简的记忆管理器" aria-hidden="true">#</a> 四、动手实践：写一个极简的记忆管理器</h2><p>看了这么多源码，是不是觉得“两步走”记忆法其实也没那么难？</p><p>光说不练假把式。今天我们就借鉴 Claude Code 的思路，用几十行 Node.js 代码，写一个能自动防爆的<strong>极简本地记忆管理器</strong>。</p><p>你可以把下面这段代码保存为 <code>MemoryManager.ts</code>，以后用大模型写脚本时，直接让它调用这个类来持久化经验。</p><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token keyword">import</span> fs <span class="token keyword">from</span> <span class="token string">&#39;fs&#39;</span><span class="token punctuation">;</span>
<span class="token keyword">import</span> path <span class="token keyword">from</span> <span class="token string">&#39;path&#39;</span><span class="token punctuation">;</span>

<span class="token keyword">export</span> <span class="token keyword">class</span> <span class="token class-name">MemoryManager</span> <span class="token punctuation">{</span>
  <span class="token keyword">private</span> memDir <span class="token operator">=</span> <span class="token string">&#39;./.ai_memory&#39;</span><span class="token punctuation">;</span>
  <span class="token keyword">private</span> indexPath <span class="token operator">=</span> path<span class="token punctuation">.</span><span class="token function">join</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">.</span>memDir<span class="token punctuation">,</span> <span class="token string">&#39;MEMORY.md&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

  <span class="token function">constructor</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// 初始化记忆目录和索引文件</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>fs<span class="token punctuation">.</span><span class="token function">existsSync</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">.</span>memDir<span class="token punctuation">)</span><span class="token punctuation">)</span> fs<span class="token punctuation">.</span><span class="token function">mkdirSync</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">.</span>memDir<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>fs<span class="token punctuation">.</span><span class="token function">existsSync</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">.</span>indexPath<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
      fs<span class="token punctuation">.</span><span class="token function">writeFileSync</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">.</span>indexPath<span class="token punctuation">,</span> <span class="token string">&#39;# 全局记忆索引\\n\\n&gt; 注意：单条记录必须少于 100 字，总行数不可超过 10 行！\\n\\n&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
  <span class="token punctuation">}</span>

  <span class="token comment">// 两步走法则的落地实现</span>
  <span class="token function">saveMemory</span><span class="token punctuation">(</span>topic<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">,</span> details<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">,</span> summary<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// Step 1: 写入详情文件（大模型可以尽情长篇大论）</span>
    <span class="token keyword">const</span> fileName <span class="token operator">=</span> <span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>topic<span class="token punctuation">.</span><span class="token function">replace</span><span class="token punctuation">(</span><span class="token regex"><span class="token regex-delimiter">/</span><span class="token regex-source language-regex">\\s+</span><span class="token regex-delimiter">/</span><span class="token regex-flags">g</span></span><span class="token punctuation">,</span> <span class="token string">&#39;_&#39;</span><span class="token punctuation">)</span><span class="token interpolation-punctuation punctuation">}</span></span><span class="token string">.md</span><span class="token template-punctuation string">\`</span></span><span class="token punctuation">;</span>
    fs<span class="token punctuation">.</span><span class="token function">writeFileSync</span><span class="token punctuation">(</span>path<span class="token punctuation">.</span><span class="token function">join</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">.</span>memDir<span class="token punctuation">,</span> fileName<span class="token punctuation">)</span><span class="token punctuation">,</span> details<span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// Step 2: 更新索引（严格限制长度）</span>
    <span class="token keyword">const</span> indexLine <span class="token operator">=</span> <span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">- [</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>topic<span class="token interpolation-punctuation punctuation">}</span></span><span class="token string">](./</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>fileName<span class="token interpolation-punctuation punctuation">}</span></span><span class="token string">): </span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>summary<span class="token punctuation">.</span><span class="token function">substring</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">,</span> <span class="token number">100</span><span class="token punctuation">)</span><span class="token interpolation-punctuation punctuation">}</span></span><span class="token template-punctuation string">\`</span></span><span class="token punctuation">;</span>
    <span class="token keyword">let</span> indexContent <span class="token operator">=</span> fs<span class="token punctuation">.</span><span class="token function">readFileSync</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">.</span>indexPath<span class="token punctuation">,</span> <span class="token string">&#39;utf-8&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    
    <span class="token comment">// 模拟源码中的防爆截断机制：超过 10 行直接抛弃最老的记忆</span>
    <span class="token keyword">const</span> lines <span class="token operator">=</span> indexContent<span class="token punctuation">.</span><span class="token function">split</span><span class="token punctuation">(</span><span class="token string">&#39;\\n&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>lines<span class="token punctuation">.</span>length <span class="token operator">&gt;</span> <span class="token number">10</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
      <span class="token builtin">console</span><span class="token punctuation">.</span><span class="token function">warn</span><span class="token punctuation">(</span><span class="token string">&#39;⚠️ 警告：记忆索引过长，触发强制截断！&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
      <span class="token comment">// 保留表头，截去最老的一条记录</span>
      indexContent <span class="token operator">=</span> lines<span class="token punctuation">.</span><span class="token function">slice</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">concat</span><span class="token punctuation">(</span>lines<span class="token punctuation">.</span><span class="token function">slice</span><span class="token punctuation">(</span><span class="token number">4</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">join</span><span class="token punctuation">(</span><span class="token string">&#39;\\n&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    fs<span class="token punctuation">.</span><span class="token function">writeFileSync</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">.</span>indexPath<span class="token punctuation">,</span> indexContent <span class="token operator">+</span> <span class="token string">&#39;\\n&#39;</span> <span class="token operator">+</span> indexLine<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token builtin">console</span><span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">✅ 记忆已保存：</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>topic<span class="token interpolation-punctuation punctuation">}</span></span><span class="token template-punctuation string">\`</span></span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token punctuation">}</span>
<span class="token punctuation">}</span>

<span class="token comment">// 测试一下</span>
<span class="token keyword">const</span> mem <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">MemoryManager</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
mem<span class="token punctuation">.</span><span class="token function">saveMemory</span><span class="token punctuation">(</span><span class="token string">&#39;Git_Bug&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;今天修复了一个由 rebase 引发的惊天血案...&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;千万不要在公共分支使用 rebase&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>只要掌握了这个思想，你完全可以把它封装成 MCP 服务，给市面上所有的通用大模型加上一个不会爆 Token 的“外置海马体”。</p><hr><h2 id="五、小结" tabindex="-1"><a class="header-anchor" href="#五、小结" aria-hidden="true">#</a> 五、小结</h2><p>通过对这三大模块的源码剖析，我们发现了 Claude Code 团队非常务实的工程智慧：</p><ul><li><strong>不要幻想模型完美</strong>：与其指望模型每次都聪明地总结，不如用硬性的 <code>stripImages</code> 和强制截断来兜底。</li><li><strong>KISS 原则（Keep It Simple, Stupid）</strong>：抛弃了花里胡哨的向量数据库，用最原始的文件系统 + 优秀的 Prompt 规训，反而做到了最好的稳定性和可读性。</li><li><strong>沙箱即正义</strong>：利用原生的 <code>Git Worktree</code> 实现代码级别的沙箱隔离，让并发试错真正有了底气。</li></ul><p>如果你能读懂这几部分源码，你完全有能力跳出“提示词工程师”的圈子，自己写出一个真正有生命力的 Agent 框架。</p><hr><h2 id="六、推荐阅读" tabindex="-1"><a class="header-anchor" href="#六、推荐阅读" aria-hidden="true">#</a> 六、推荐阅读</h2>`,59)),s("ul",null,[s("li",null,[s("a",r,[n[0]||(n[0]=a("Git Worktree 官方文档",-1)),p(t)]),n[1]||(n[1]=a(" —— 强烈建议学习这个冷门但极其实用的 Git 命令，它是实现安全沙箱的核心。",-1))]),s("li",null,[s("a",k,[n[2]||(n[2]=a("Anthropic: Context Window Management",-1)),p(t)]),n[3]||(n[3]=a(" —— 官方教你如何科学地管理长上下文。",-1))])])])}const g=e(u,[["render",d],["__file","04-memory-and-context.html.vue"]]);export{g as default};
